const raw = ($input.first()?.json?.text ?? $input.first()?.json?.output ?? '').toString();
let facts = [];

const stripOuterQuotes = (value) => String(value ?? '')
  .replace(/^[\'\"“”]+|[\'\"“”]+$/g, '')
  .trim();

const removeVietnameseMarks = (value) => value
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D');

const normalizePhone = (value) => {
  const raw = String(value ?? '').replace(/[^\d+]/g, '');
  let phone = raw;
  if (phone.startsWith('+84')) phone = '0' + phone.slice(3);
  if (phone.startsWith('84') && phone.length >= 11) phone = '0' + phone.slice(2);
  return /^0\d{8,10}$/.test(phone) ? phone : null;
};

const canonicalize = (value) => {
  const stripped = stripOuterQuotes(value);
  const phone = normalizePhone(stripped);
  if (phone) return `phone:${phone}`;

  return removeVietnameseMarks(stripped)
    .toLowerCase()
    .replace(/^(nguoi dung|ung vien|ban ay|ban)\s+/i, '')
    .replace(/^(sdt|so dien thoai|dien thoai|khu vuc|nghe mong muon|muon|muon tim viec|ten la)[:\s-]*/i, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const normalizeFact = (value) => stripOuterQuotes(value)
  .replace(/\s+/g, ' ')
  .trim();

const isUsefulFact = (fact) => {
  if (!fact) return false;
  if (fact.length < 6 || fact.length > 240) return false;
  if (/^(xin chào|chào bạn|cảm ơn|tôi có thể|bạn đang muốn|bạn có muốn)/i.test(fact)) return false;
  if (/^(tên công việc|công ty\/?đối tác|địa điểm|mức lương|yêu cầu cơ bản|quyền lợi):/i.test(fact)) return false;
  return true;
};

// Root-cause guard: NEVER coerce an object with String() (that yields "[object Object]").
const toFactString = (entry) => {
  if (typeof entry === 'string') return entry;
  if (typeof entry === 'number' || typeof entry === 'boolean') return String(entry);
  if (entry !== null && typeof entry === 'object') {
    // Salvage a single {key:"value"} pair; ambiguous objects are dropped, never guessed.
    const strVals = Object.values(entry).filter((v) => typeof v === 'string' && v.trim().length);
    return strVals.length === 1 ? strVals[0] : null;
  }
  return null;
};

try {
  let text = raw.trim()
    .replace(/^\x60\x60\x60(?:json)?/i, '')
    .replace(/\x60\x60\x60$/i, '')
    .trim();
  const start = text.indexOf('[');
  const end = text.lastIndexOf(']');
  if (start !== -1 && end !== -1 && end > start) text = text.slice(start, end + 1);

  const parsed = JSON.parse(text);

  // Tolerate LLMs that wrap the array in an object, e.g. { "facts": [...] }.
  let list = parsed;
  if (!Array.isArray(list) && parsed && typeof parsed === 'object') {
    const inner = Object.values(parsed).find((v) => Array.isArray(v));
    if (inner) list = inner;
  }

  if (Array.isArray(list)) {
    const seen = new Set();
    facts = list
      .map(toFactString)
      .filter((entry) => typeof entry === 'string' && entry.trim().length)
      .map(normalizeFact)
      .filter(isUsefulFact)
      .filter((fact) => fact.toLowerCase() !== '[object object]')
      .map((content) => ({ content, canonical_key: canonicalize(content) }))
      .filter((fact) => fact.canonical_key)
      .filter((fact) => {
        if (seen.has(fact.canonical_key)) return false;
        seen.add(fact.canonical_key);
        return true;
      });
  }
} catch (error) {
  facts = [];
}

return facts.slice(0, 10).map((fact) => ({ json: { ...fact, source: 'candidate' } }));

const stripOuterQuotes = (value) => String(value ?? '')
  .replace(/^['\"“”]+|['\"“”]+$/g, '')
  .trim();

const removeVietnameseMarks = (value) => value
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D');

const normalizePhone = (value) => {
  const raw = String(value ?? '').replace(/[^\d+]/g, '');
  let phone = raw;
  if (phone.startsWith('+84')) phone = '0' + phone.slice(3);
  if (phone.startsWith('84') && phone.length >= 11) phone = '0' + phone.slice(2);
  return /^0\d{8,10}$/.test(phone) ? phone : null;
};

const canonicalize = (value) => {
  const stripped = stripOuterQuotes(value);
  const phone = normalizePhone(stripped);
  if (phone) return 'phone:' + phone;

  return removeVietnameseMarks(stripped)
    .toLowerCase()
    .replace(/^(nguoi dung|ung vien|ban ay|ban)\s+/i, '')
    .replace(/^(sdt|so dien thoai|dien thoai|khu vuc|nghe mong muon|muon|muon tim viec|ten la)[:\s-]*/i, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const context = $('Prepare Memory Context').first()?.json ?? {};
const chatId = stripOuterQuotes(context.chat_id);
if (!chatId) {
  return [];
}

const all = $input.all();
const candidates = all
  .filter((item) => item.json.source === 'candidate')
  .map((item) => ({
    content: stripOuterQuotes(item.json.content),
    canonical_key: item.json.canonical_key || canonicalize(item.json.content),
  }))
  .filter((item) => item.content.length >= 6 && item.content.length <= 240 && item.canonical_key);

const existing = new Set(
  all
    .filter((item) => item.json.source === 'existing')
    .flatMap((item) => [
      item.json.metadata?.canonical_key,
      canonicalize(item.json.content),
    ])
    .filter(Boolean)
);

const seen = new Set();
const novel = [];
for (const item of candidates) {
  if (existing.has(item.canonical_key) || seen.has(item.canonical_key)) continue;
  seen.add(item.canonical_key);
  novel.push(item);
}

return novel.map((item) => ({
  json: {
    content: item.content,
    canonical_key: item.canonical_key,
    chat_id: chatId,
    zalo_id: chatId,
  },
}));

const ctx = $input.first()?.json ?? {};
const u = String(ctx.user_text ?? '').trim().toLowerCase();
// HIGH-PRECISION skip: only pure greetings/affirmations/emoji or <3 chars.
// Anything substantive runs the extractor as before — never silently drops a real fact.
const skip = u.length < 3 || ['ok','okie','oke','okay','okey','yes','no','da','dạ','vang','vâng','dung','đúng','sai','cam on','cảm ơn','cám ơn','thank','thanks','hi','hey','hello','chao','chào','xin chao','xin chào','ad','admin','👍','👌','😊','😄','🎉'].includes(u);
if (skip) return [];
return [{ json: ctx }];
